WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM sessions), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT island_id, DATE_TRUNC('MONTH', started_at) AS activity_month, AVG(island_id) AS avg_island_id, COUNT(CASE WHEN browser = 'Edge' THEN 1 END) AS edge_count, ROUND(AVG(session_start_flag), 2) AS avg_session_start_flag, ROUND(SUM(island_id) / NULLIF(COUNT(CASE WHEN device = 'tablet' THEN 1 END), 0), 2) AS island_id_per_tablet, COUNT(CASE WHEN browser = 'Safari' THEN 1 END) AS safari_count, COUNT(*) AS num_rows FROM sessionized GROUP BY island_id, DATE_TRUNC('MONTH', started_at) ORDER BY safari_count;
